  if (dev == NULL || dev->ops == NULL ||
      dev->ops->transmit == NULL || dev->ops->receive == NULL)
    {
      nerr("ERROR: Invalid lower half device\n");
      return -EINVAL;
    }

  if (dev->quota_ptr == NULL)
