   * table these two install.
   *
   * Skipping them is not a link error.  The table lives in .bss as
   * g_rf_funcs_t and starts out NULL, so the closed RF code simply branches
   * through offset 16 of address zero -- an instruction bus fault, in a
   * library with no source, several frames away from anything we wrote.
   */

  bk_phy_adapter_init();
  bk_rf_adapter_init();

  return bk_wifi_init(&config);
}

